with enriched as (select id, plan, start_date, end_date, monthly_fee, status, sum(monthly_fee) over (partition by status order by start_date, id rows between unbounded preceding and current row) as running_sum_monthly_fee, max(monthly_fee) over (partition by status order by start_date, id rows between unbounded preceding and current row) as running_max_monthly_fee, avg(monthly_fee) over (partition by status order by start_date, id rows between unbounded preceding and current row) as running_avg_monthly_fee from subscriptions) select id, plan, start_date, end_date, monthly_fee, running_max_monthly_fee, case when plan rlike '^(premium|standard)$' then 'GROUP_A' when plan rlike '^(basic|enterprise)$' then 'CORE' else 'GROUP_B' end as plan_zone from enriched;
